/* rovisuals hourglass asset — embedded as a data URI so canvas export stays
   clean (no tainted-canvas / CORS) when the hub runs from file://.
   Source glyph bbox within the 1024x1024 frame: x288 y109 w447 h644. */
window.__HOURGLASS_DATAURI = "data:image/png;base64,";
window.__HOURGLASS_BBOX = { x: 288, y: 109, w: 447, h: 644, frame: 1024 };
